import * as React from 'react';
import * as BentoGridPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface BentoGridProps extends React.ComponentPropsWithoutRef<typeof BentoGridPrimitive.BentoGrid> {
  className?: string;
}

export const BentoGrid = React.forwardRef<HTMLDivElement, BentoGridProps>(
  ({ className, children, ...props }, ref) => (
    <BentoGridPrimitive.BentoGrid
      ref={ref}
      className={clsx(
        'grid grid-cols-1 md:grid-cols-3 gap-6 auto-rows-[22rem] max-w-7xl mx-auto w-full',
        className
      )}
      {...props}
    >
      {children}
    </BentoGridPrimitive.BentoGrid>
  )
);
BentoGrid.displayName = 'BentoGrid';

