import { Component, JSX, splitProps } from 'solid-js';
import * as BentoGridPrimitive from '@exhuma/core';

export interface BentoGridProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const BentoGrid: Component<BentoGridProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <BentoGridPrimitive.BentoGrid
      class={`grid grid-cols-1 md:grid-cols-3 gap-6 auto-rows-[22rem] max-w-7xl mx-auto w-full ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </BentoGridPrimitive.BentoGrid>
  );
};

