import { BentoGrid } from '@exhuma/core';

class ExhumaBentoGridElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-bento-grid');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-bento-grid')) {
  customElements.define('exhuma-bento-grid', ExhumaBentoGridElement);
